import { fileURLToPath } from 'node:url';
import { defineConfig } from 'vitest/config';

// Tests run against package SOURCE so `pnpm -r test` works without a build.
// `pnpm -r build` + `pnpm typecheck` separately prove the emitted artifact.
// Vector files under vectors/ are committed golden artifacts regenerated by
// `pnpm gen-vectors` (gen-vectors.mjs runs against the built dist/).
export default defineConfig({
  resolve: {
    alias: {
      '@tessera/types': fileURLToPath(
        new URL('../../packages/types/src/index.ts', import.meta.url),
      ),
      '@tessera/identity': fileURLToPath(
        new URL('../../packages/identity/src/index.ts', import.meta.url),
      ),
    },
  },
  test: {
    include: ['src/**/*.test.ts'],
  },
});
